// V0.2.1 Bestiary and elemental affinities. An entry unlocks after you defeat that spirit once.
// Weak element: +30% damage. Resisted element: -25% damage. Rituals and burning are neutral.
import {weapon} from './catalog.js';
import {healthForTier} from './balance.js';
export const ELEMENTS={fire:['Fire','Огонь','Ugnis'],ice:['Ice','Лёд','Ledas'],poison:['Poison','Яд','Nuodai'],thunder:['Thunder','Гром','Griaustinis'],slash:['Slash','Рубящий','Kirtis'],pierce:['Pierce','Колющий','Dūris'],holy:['Holy light','Святой свет','Šventa šviesa'],shadow:['Shadow','Тень','Šešėlis'],death:['Death','Смерть','Mirtis'],water:['Water','Вода','Vanduo']};
const CLASSIC={iron_bell:'holy',amber_needle:'pierce',ember_coil:'fire',spring_vessel:'water',ash_raven:'shadow',thread_spindle:'slash',hollow_crown:'slash',star_seed:'holy',moon_sickle:'slash',thorn_lantern:'fire',grave_compass:'death',storm_chime:'thunder'};
export function weaponElement(id){const w=weapon(id);if(!w)return null;if(w.element)return w.element;const base=w.baseId||(w.components&&weapon(w.components[0])?.baseId)||w.id;return CLASSIC[base]||weapon(base)?.element||null;}
const L=(en,ru,lt)=>({en,ru,lt});
// Each tier sprite is one kind of spirit. Speeds follow the three movement archetypes.
export const SPIRITS=[
 {id:'husk',tier:1,name:L('Husk','Шелуха','Lukštas'),lore:L('An empty shell that still walks the old roads.','Пустая оболочка, всё ещё бродящая по старым дорогам.','Tuščias apvalkalas, vis dar klaidžiojantis senais keliais.'),weak:['fire'],resist:[]},
 {id:'nightwing',tier:2,name:L('Nightwing','Ночекрыл','Naktasparnis'),lore:L('Swift and hungry; it circles before it bites.','Быстрый и голодный, кружит перед укусом.','Greitas ir alkanas; prieš kąsdamas suka ratus.'),weak:['pierce','thunder'],resist:['poison']},
 {id:'rootguard',tier:3,name:L('Rootguard','Корнестраж','Šaknų sargas'),lore:L('Bark over bone. Burns well, cuts well.','Кора поверх костей. Хорошо горит и рубится.','Žievė ant kaulų. Gerai dega, gerai kertasi.'),weak:['fire','slash'],resist:['poison','water']},
 {id:'hollowguard',tier:4,name:L('Hollowguard','Пустостраж','Tuščiasargis'),lore:L('Rusted armour with nothing inside but a cold wind.','Ржавые латы, внутри лишь холодный ветер.','Surūdiję šarvai, o viduje tik šaltas vėjas.'),weak:['thunder'],resist:['pierce','slash']},
 {id:'banshee',tier:5,name:L('Banshee','Банши','Raudotoja'),lore:L('Her wail chills the blood. Steel passes through her.','Её вой леденит кровь. Сталь проходит сквозь неё.','Jos rauda stingdo kraują. Plienas pereina kiaurai.'),weak:['holy'],resist:['slash','pierce']},
 {id:'antlerfiend',tier:6,name:L('Antlerfiend','Рогатый бес','Ragų velnias'),lore:L('Hot-blooded and horned; only frost slows it down.','Горячая кровь и рога; только мороз его замедляет.','Karštakraujis ir raguotas; tik šaltis jį sulėtina.'),weak:['ice','water'],resist:['fire']},
 {id:'dreadknight',tier:7,name:L('Dreadknight','Рыцарь ужаса','Siaubo riteris'),lore:L('An oath that outlived its knight.','Клятва, пережившая своего рыцаря.','Priesaika, pergyvenusi savo riterį.'),weak:['thunder','death'],resist:['slash','pierce']},
 {id:'voidarchon',tier:8,name:L('Void Archon','Архонт пустоты','Tuštumos archontas'),lore:L('It drinks the dark. Only true light hurts it.','Он пьёт тьму. Ранит его лишь истинный свет.','Jis geria tamsą. Sužeisti jį gali tik tikra šviesa.'),weak:['holy'],resist:['shadow','ice']},
 {id:'guardian',guardian:true,name:L('Guardian','Страж','Sargas'),lore:L('Appears three times each stage. Carries an Evolution core.','Появляется трижды за этап. Несёт ядро эволюции.','Pasirodo tris kartus per etapą. Neša evoliucijos branduolį.'),weak:['death'],resist:[]}
];
export const BOSS_LORE={
 scarecrow:{lore:L('Stuffed with straw and old grudges. Its crows see everything.','Набит соломой и старыми обидами. Его вороны видят всё.','Prikimštas šiaudų ir senų nuoskaudų. Jo varnos mato viską.'),weak:['fire'],resist:['pierce'],moves:L('Crow fans (stand in the gap), straw dolls, scythe dash, crow ring.','Веер ворон (стой в проходе), соломенные куклы, рывок с косой, кольцо ворон.','Varnų vėduoklė (stovėk tarpe), šiaudų lėlės, puolimas su dalgiu, varnų žiedas.')},
 werewolf:{lore:L('A grave hound that remembers being a man on moonless nights.','Кладбищенский пёс, что в безлунные ночи помнит, что был человеком.','Kapų šuo, kuris bemėnulėmis naktimis prisimena buvęs žmogus.'),weak:['holy'],resist:['poison'],moves:L('Pounces that track you, claw sweeps, howl that summons a pack.','Прыжки за тобой, удары когтями, вой, зовущий стаю.','Šuoliai paskui tave, nagų kirčiai, kaukimas, šaukiantis gaują.')},
 bellkeeper:{lore:L('The village bells answer only to him.','Деревенские колокола отвечают лишь ему.','Kaimo varpai klauso tik jo.'),weak:['thunder'],resist:['holy'],moves:L('Toll rings with a moving gap, falling bells, bell pillars, a shrinking cage.','Кольца звона с проходом, падающие колокола, столпы, сужающаяся клетка.','Varpų žiedai su judančiu tarpu, krentantys varpai, stulpai, besitraukiantis narvas.')},
 kaukas:{lore:L('A little house spirit gone bad. It stole the quarry lantern.','Домовой, ставший злым. Он украл фонарь карьера.','Pagedęs namų dvasiukas. Jis pavogė karjero žibintą.'),weak:['ice'],resist:['fire'],moves:L('Blinks around you, spark bursts, lantern mines, steals the light.','Телепорты вокруг, искры, фонарные мины, крадёт свет.','Teleportuojasi aplink, kibirkščių papliūpos, žibintų minos, vagia šviesą.')},
 stonebreather:{lore:L('The quarry learned to breathe, and this is its lung.','Карьер научился дышать, и это его лёгкое.','Karjeras išmoko kvėpuoti, ir tai jo plautis.'),weak:['thunder','water'],resist:['slash','pierce'],moves:L('Burrows under you, rolling boulders with one safe lane, rock lines, dust breath.','Подкоп под тобой, катящиеся валуны с безопасной полосой, каменные линии, пыльное дыхание.','Rausiasi po tavimi, riedantys rieduliai su viena saugia juosta, akmenų linijos, dulkių kvapas.')},
 miller:{lore:L('The drowned miller still turns the wheel.','Утонувший мельник всё ещё вращает колесо.','Paskendęs malūnininkas vis dar suka ratą.'),weak:['fire'],resist:['water','ice'],moves:L('Mill-wheel spirals with gaps, flour clouds, sluice charges.','Спирали мельничного колеса, мучные облака, рывки.','Malūno rato spiralės su tarpais, miltų debesys, puolimai.')},
 laume:{lore:L('A water fairy of the weir. Her songs drag you under.','Водяная фея плотины. Её песни тянут на дно.','Užtvankos laumė. Jos dainos tempia į dugną.'),weak:['thunder'],resist:['water','fire'],moves:L('Sweeping waves with one gap, whirlpools that pull, water clones.','Волны с одним проходом, затягивающие водовороты, водяные двойники.','Bangos su vienu tarpu, traukiantys sūkuriai, vandens antrininkės.')},
 witch:{lore:L('Every mirror in the marsh is one of her eyes.','Каждое зеркало болота — один из её глаз.','Kiekvienas pelkės veidrodis yra viena jos akis.'),weak:['holy'],resist:['shadow'],moves:L('Mirror clones (only one is real), bouncing hexes, glass rain.','Зеркальные двойники (лишь одна настоящая), отражённые проклятия, стеклянный дождь.','Veidrodžių antrininkės (tikra tik viena), atšokantys kerai, stiklo lietus.')},
 heron:{lore:L('A heron of glass that hunts reflections.','Стеклянная цапля, охотящаяся на отражения.','Stiklinis garnys, medžiojantis atspindžius.'),weak:['thunder','slash'],resist:['pierce'],moves:L('Marked dives, shard rain, shattering rings.','Отмеченные пикирования, дождь осколков, разбивающиеся кольца.','Pažymėti smigimai, šukių lietus, dūžtantys žiedai.')},
 antlerking:{lore:L('King of the old forest, crowned with antlers.','Король старого леса, увенчанный рогами.','Senosios girios karalius su ragų karūna.'),weak:['fire'],resist:['slash'],moves:L('Charges, erupting roots, antler throws.','Рывки, вырастающие корни, броски рогов.','Puolimai, iš žemės kylančios šaknys, ragų metimai.')},
 serpentking:{lore:L('The Žaltys king coils around the first bell.','Король ужей обвивает первый колокол.','Žalčių karalius apsivijęs pirmąjį varpą.'),weak:['ice','holy'],resist:['poison'],moves:L('A long body that sweeps the arena, venom spit, a constricting ring.','Длинное тело, метущее арену, ядовитые плевки, сжимающееся кольцо.','Ilgas kūnas šluoja areną, nuodų spjūviai, smaugiantis žiedas.')},
 legacy:{lore:L('An older keeper of these roads.','Старый хранитель этих дорог.','Senesnis šių kelių sergėtojas.'),weak:[],resist:[],moves:L('Volleys, marks, charges and rings.','Залпы, метки, рывки и кольца.','Salvės, žymės, puolimai ir žiedai.')}
};
export const spiritKey=e=>e.boss?(e.bossId||'legacy'):e.mini?'guardian':SPIRITS[Math.max(0,Math.min(7,(e.tier||1)-1))].id;
function affinity(key){const s=SPIRITS.find(x=>x.id===key);return s||BOSS_LORE[key]||{weak:[],resist:[]};}
export function elementFactor(e,d){if(!d||d.ritual||!d.weaponId||e.kind==='crate')return 1;const el=weaponElement(d.weaponId);if(!el)return 1;const a=affinity(spiritKey(e));return a.weak.includes(el)?1.3:a.resist.includes(el)?.75:1;}
export const spiritStats=s=>s.guardian?{hp:'600+',damage:27,speed:83,xp:12}:{hp:healthForTier(s.tier),damage:10+s.tier*3,speed:`51–${89+12}`,xp:s.tier<=2?1:s.tier<=4?3:9};
export function recordSlain(r,e){const key=spiritKey(e);r.slain||={};r.slain[key]=(r.slain[key]||0)+1;}
export function mergeSlain(s,r){s.bestiary||={};for(const [k,n] of Object.entries(r.slain||{}))if(Number.isSafeInteger(n)&&n>0)s.bestiary[k]=(s.bestiary[k]||0)+n;}
